from __future__ import annotations

import pytest


@pytest.fixture(autouse=True)
def _cursor_secrets(monkeypatch):
    monkeypatch.setenv("PWC_MCP_CURSOR_KEY_CURRENT", "test-current-cursor-secret")
    monkeypatch.delenv("PWC_MCP_CURSOR_KEY_PREVIOUS", raising=False)

"""Every read-only CLI command is a tool, and every research flag a parameter."""

from __future__ import annotations

import argparse
import asyncio

from mcp.client import Client
from pwc_cli import queries
from pwc_mcp.server import (
    ENTITY_PARAMETERS,
    MCP_ONLY_PARAMETERS,
    PARAMETER_NAMES,
    TOOL_COMMANDS,
    build_server,
    cli_options,
)
from test_server import StubCatalog

# Deliberate default divergences from the CLI, documented in README.md: the
# hosted service caps rows per response at 25 (list_benchmarks and list_tasks
# leave the row count to the server instead of the CLI's 50).
DEFAULT_EXCEPTIONS = {
    ("list_benchmarks", "limit"): None,
    ("list_methods", "limit"): 25,
    ("list_tasks", "limit"): None,
}
# argparse placeholders for "not given"; the MCP schema spells these as null.
UNSET_DEFAULTS = (None, argparse.SUPPRESS, (), [])


def _tools():
    async def exercise():
        async with Client(build_server(StubCatalog())) as client:
            return {tool.name: tool for tool in (await client.list_tools()).tools}

    return asyncio.run(exercise())


def _enum_values(schema, root):
    if "$ref" in schema:
        schema = root["$defs"][schema["$ref"].rsplit("/", 1)[1]]
    values = list(schema.get("enum") or [])
    for branch in schema.get("anyOf") or []:
        values.extend(_enum_values(branch, root))
    return values


def _mcp_name(tool: str, destination: str) -> str:
    if destination == "name":
        return ENTITY_PARAMETERS[tool]
    return PARAMETER_NAMES.get(destination, destination)


def test_every_read_only_cli_command_has_exactly_one_tool():
    assert sorted(TOOL_COMMANDS.values()) == sorted(queries.READ_ONLY_COMMANDS)
    assert len(set(TOOL_COMMANDS.values())) == len(TOOL_COMMANDS)


def test_every_cli_research_flag_is_a_tool_parameter_and_vice_versa():
    tools = _tools()

    assert set(tools) == set(TOOL_COMMANDS)
    for tool, command in TOOL_COMMANDS.items():
        cli = queries.query_options(command)
        schema = tools[tool].input_schema
        parameters = set(schema["properties"]) - MCP_ONLY_PARAMETERS.get(
            tool, frozenset()
        )
        mapped = cli_options(tool, **dict.fromkeys(parameters))

        assert set(mapped) == set(cli), tool
        for destination, action in cli.items():
            parameter = _mcp_name(tool, destination)
            property_schema = schema["properties"][parameter]
            if isinstance(action, argparse._StoreTrueAction):
                assert property_schema.get("type") == "boolean", (tool, parameter)
            elif action.choices and set(action.choices) != {"true", "false"}:
                assert set(action.choices) <= set(
                    _enum_values(property_schema, schema)
                ), (
                    tool,
                    parameter,
                )
            if not action.option_strings or destination == "name":
                assert parameter in schema["required"], (tool, parameter)
            # Same arguments must mean the same query through `pwc` and the MCP
            # tools, so every CLI default is the tool default unless documented.
            if action.default not in UNSET_DEFAULTS:
                expected = DEFAULT_EXCEPTIONS.get((tool, parameter), action.default)
                assert property_schema.get("default") == expected, (tool, parameter)


def test_paper_references_and_entity_names_are_required_everywhere():
    tools = _tools()

    for tool, entity in ENTITY_PARAMETERS.items():
        assert tools[tool].input_schema["required"] == [entity]
    for tool in (
        "get_paper_info",
        "get_paper_evaluations",
        "read_paper",
        "get_related_papers",
        "get_paper_lineage",
    ):
        assert tools[tool].input_schema["required"] == ["paper"]

from __future__ import annotations

import json

import pytest
from pwc_cli.cli import UsageError
from pwc_cli.transport import Response, ResponseError
from pwc_mcp.catalog import (
    CatalogClient,
    PublicPaperMiss,
    cache_ttl,
    near_title,
    normalize_title,
)


class StubTransport:
    def __init__(self, routes):
        self.routes = routes
        self.calls = []

    def get(self, path, params=None):
        self.calls.append((path, params))
        value = self.routes[path]
        if isinstance(value, str):
            return Response(value.encode(), {"content-type": "text/markdown"})
        return Response(
            json.dumps(value).encode(), {"content-type": "application/json"}
        )


def test_catalog_normalizes_paper_urls_and_caches_identical_reads():
    transport = StubTransport(
        {
            "papers/1706.03762": {"id": "755", "title": "Attention Is All You Need"},
        }
    )
    catalog = CatalogClient(transport=transport)

    first = catalog.query(
        ("paper", "info"),
        {"paper": "https://arxiv.org/pdf/1706.03762v7.pdf", "include_resources": True},
    )
    second = catalog.query(
        ("paper", "info"),
        {
            "paper": "https://huggingface.co/papers/1706.03762",
            "include_resources": True,
        },
    )

    assert first == second
    assert transport.calls == [("papers/1706.03762", {"include_resources": True})]


def test_catalog_reads_one_version_bound_markdown_chunk_per_call():
    version = "a" * 64

    class ChunkTransport:
        def __init__(self):
            self.calls = []

        def get(self, path, params=None):
            self.calls.append((path, params))
            if params["offset"] == 0:
                return Response(
                    "α first".encode(),
                    {
                        "x-pwc-truncated": "1",
                        "x-pwc-content-version": version,
                        "x-pwc-next-offset": "8",
                    },
                )
            return Response(
                b" terminal",
                {
                    "x-pwc-truncated": "0",
                    "x-pwc-content-version": version,
                },
            )

    transport = ChunkTransport()
    catalog = CatalogClient(transport=transport)
    first = catalog.read_paper_chunk("1706.03762", limit=65_536)
    second = catalog.read_paper_chunk(
        "1706.03762",
        offset=first.next_offset,
        content_version=first.content_version,
        limit=65_536,
        resolved=True,
    )

    assert first.markdown == "α first"
    assert first.next_offset == 8
    assert second.markdown == " terminal"
    assert second.next_offset is None
    assert transport.calls == [
        (
            "research/papers/1706.03762/read",
            {"offset": 0, "limit": 65_536, "content_version": None},
        ),
        (
            "research/papers/1706.03762/read",
            {"offset": 8, "limit": 65_536, "content_version": version},
        ),
    ]


def test_catalog_caches_versioned_chunks_and_rejects_nonadvancing_offsets():
    version = "b" * 64

    class ChunkTransport:
        def __init__(self):
            self.calls = 0

        def get(self, _path, _params=None):
            self.calls += 1
            return Response(
                b"data",
                {
                    "x-pwc-truncated": "1",
                    "x-pwc-content-version": version,
                    "x-pwc-next-offset": "4",
                },
            )

    transport = ChunkTransport()
    catalog = CatalogClient(transport=transport)
    with pytest.raises(ResponseError, match="did not advance"):
        catalog.read_paper_chunk(
            "1706.03762",
            offset=4,
            content_version=version,
            resolved=True,
        )
    assert transport.calls == 1


def test_catalog_versioned_chunk_cache_avoids_repeated_upstream_reads():
    version = "c" * 64

    class ChunkTransport:
        def __init__(self):
            self.calls = 0

        def get(self, _path, _params=None):
            self.calls += 1
            return Response(
                b"done",
                {
                    "x-pwc-truncated": "0",
                    "x-pwc-content-version": version,
                },
            )

    transport = ChunkTransport()
    catalog = CatalogClient(transport=transport)
    first = catalog.read_paper_chunk(
        "1706.03762",
        offset=8,
        content_version=version,
        resolved=True,
    )
    second = catalog.read_paper_chunk(
        "1706.03762",
        offset=8,
        content_version=version,
        resolved=True,
    )

    assert first == second
    assert transport.calls == 1


def test_catalog_resolves_exact_titles_and_rejects_ambiguous_titles():
    transport = StubTransport(
        {
            "papers/search": {
                "results": [
                    {"id": "1", "arxiv_id": "1111.11111", "title": "Same Title"},
                    {"id": "2", "arxiv_id": "2222.22222", "title": "Same Title"},
                ]
            }
        }
    )
    catalog = CatalogClient(transport=transport)

    with pytest.raises(ResponseError, match="ambiguous"):
        catalog.query(("paper", "lineage", "list"), {"paper": "Same Title"})


def test_catalog_resolves_pwc_urls_and_dotted_legacy_arxiv_ids():
    transport = StubTransport(
        {
            "papers/search": {
                "results": [
                    {
                        "id": "755",
                        "arxiv_id": "1706.03762",
                        "title": "Attention Is All You Need",
                    }
                ]
            },
            "papers/1706.03762": {"id": "755"},
            "papers/math.GT%2F0309136": {"id": "900"},
        }
    )
    catalog = CatalogClient(transport=transport)

    assert catalog.query(
        ("paper", "info"),
        {"paper": "https://paperswithcode.co/paper/attention-is-all-you-need"},
    ) == {"id": "755"}
    assert catalog.query(("paper", "info"), {"paper": "math.GT/0309136"}) == {
        "id": "900"
    }


def test_catalog_checks_later_search_pages_for_ambiguous_exact_titles():
    class PaginatedTransport:
        def get(self, path, params=None):
            assert path == "papers/search"
            page = params["page"]
            payload = {
                "results": [
                    {
                        "id": str(page),
                        "arxiv_id": f"1111.1111{page}",
                        "title": "Same Title",
                    }
                ],
                "next_page": 2 if page == 1 else None,
            }
            return Response(json.dumps(payload).encode(), {})

    catalog = CatalogClient(transport=PaginatedTransport())

    with pytest.raises(ResponseError, match="ambiguous"):
        catalog.query(("paper", "lineage", "list"), {"paper": "Same Title"})


def test_catalog_fails_closed_when_paper_filters_are_not_confirmed():
    transport = StubTransport({"papers/": {"results": [], "applied_filters": {}}})
    catalog = CatalogClient(transport=transport)

    with pytest.raises(ResponseError, match="did not confirm"):
        catalog.query(("paper", "list"), {"task": "image-classification"})


def test_catalog_query_runs_cli_commands_with_per_path_cache_lifetimes():
    transport = StubTransport(
        {
            "datasets/": {"results": [{"id": "72", "name": "ImageNet-1k"}]},
            "datasets/72/evaluations/": {
                "count": 1,
                "results": [{"id": "1", "model_name": "A", "metrics": {"top1": 80}}],
            },
        }
    )
    catalog = CatalogClient(transport=transport)

    first = catalog.query(("benchmark",), {"name": "ImageNet-1k", "limit": 5})
    second = catalog.query(("benchmark",), {"name": "imagenet-1k", "limit": 5})

    assert first == second
    assert first["results"][0]["model_name"] == "A"
    assert first["count"] == 1
    # The second lookup differs only in the search text; the identical
    # evaluation request is served from the shared cache.
    assert [path for path, _params in transport.calls] == [
        "datasets/",
        "datasets/72/evaluations/",
        "datasets/",
    ]
    assert cache_ttl("papers/search") == 60
    assert cache_ttl("tasks/1/page") == 600
    assert cache_ttl("datasets/72/evaluations/") == 300


def test_catalog_query_reports_cli_usage_errors_without_upstream_calls():
    transport = StubTransport({})
    catalog = CatalogClient(transport=transport)

    with pytest.raises(UsageError, match="--limit must be 1-100"):
        catalog.query(("search",), {"query": "x", "limit": 0})
    with pytest.raises(UsageError, match="not a read-only"):
        catalog.query(("skills", "add"), {})
    assert transport.calls == []


def test_catalog_canonicalises_numeric_ids_of_arxiv_papers():
    transport = StubTransport(
        {
            "papers/86122": {"id": "86122", "arxiv_id": "2505.18132v1"},
            "papers/2505.18132": {"id": "86122", "title": "BiggerGait"},
            "papers/4242": {"id": "4242", "arxiv_id": None, "source": "external"},
        }
    )
    catalog = CatalogClient(transport=transport)

    # List tools hand out numeric IDs for arXiv papers too; the Markdown route
    # only knows arXiv papers by arXiv ID, so numeric references canonicalise.
    assert catalog.resolve_paper("86122") == "2505.18132"
    assert catalog.query(("paper", "info"), {"paper": "86122"}) == {
        "id": "86122",
        "title": "BiggerGait",
    }
    # External papers have no arXiv ID and keep their numeric reference.
    assert catalog.resolve_paper("4242") == "4242"
    assert transport.calls[0] == ("papers/86122", {})


def test_catalog_rejects_unsupported_urls_without_searching():
    transport = StubTransport({})
    catalog = CatalogClient(transport=transport)

    for url in (
        "https://doi.org/10.1007/s10479-024-06277-x",
        "https://aclanthology.org/2026.acl-long.200/",
    ):
        with pytest.raises(ResponseError, match="Paper URL not supported"):
            catalog.resolve_paper(url)
    assert transport.calls == []


def test_catalog_distinguishes_missing_papers_from_missing_markdown():
    from pwc_cli.transport import HTTPStatusError

    class MissingTransport:
        def __init__(self, paper_exists):
            self.paper_exists = paper_exists

        def get(self, path, params=None):
            if path.endswith("/read"):
                raise HTTPStatusError(404, "Paper Markdown was not found")
            if self.paper_exists:
                return Response(b'{"id": "1"}', {})
            raise HTTPStatusError(404, "No paper found")

    with pytest.raises(ResponseError, match="Paper not found: 2308.10195"):
        CatalogClient(transport=MissingTransport(False)).read_paper_chunk(
            "2308.10195", resolved=True
        )
    with pytest.raises(HTTPStatusError) as missing_markdown:
        CatalogClient(transport=MissingTransport(True)).read_paper_chunk(
            "2505.18132", resolved=True
        )
    assert missing_markdown.value.status == 404


def test_catalog_reports_titles_missing_from_an_empty_search_as_not_found():
    # The public API answers an unknown title with an empty result list; that
    # must surface as "title not found", not as a malformed response.
    transport = StubTransport(
        {
            "papers/search": {
                "next_page": None,
                "previous_page": None,
                "results": [],
                "applied_filters": {},
            }
        }
    )
    catalog = CatalogClient(transport=transport)

    with pytest.raises(ResponseError, match="Paper title not found: Dropout"):
        catalog.resolve_paper("Dropout: A Simple Way to Prevent Overfitting")
    # One phrase query, then one plain keyword query as the fallback.
    assert [params["q"] for _path, params in transport.calls] == [
        '"Dropout: A Simple Way to Prevent Overfitting"',
        "Dropout: A Simple Way to Prevent Overfitting",
    ]


EXACT_TITLE_ROW = {"id": "755", "arxiv_id": "1706.03762", "title": "Attention Is All You Need"}


class TitleSearchTransport:
    """Keyword search whose plain results never end; the phrase query is small."""

    def __init__(self, *, phrase_results, plain_has_exact):
        self.phrase_results = phrase_results
        self.plain_has_exact = plain_has_exact
        self.calls = []

    def get(self, path, params=None):
        params = dict(params or {})
        self.calls.append((path, params))
        assert path == "papers/search"
        page = params["page"]
        if params["q"].startswith('"'):
            body = {"results": self.phrase_results, "next_page": None}
        else:
            rows = [
                {"id": str(page * 100 + i), "arxiv_id": f"2{page:03d}.{i:05d}", "title": f"Attention {i}"}
                for i in range(100)
            ]
            if self.plain_has_exact and page == 1:
                rows[0] = EXACT_TITLE_ROW
            body = {"results": rows, "next_page": page + 1}
        return Response(json.dumps(body).encode(), {"content-type": "application/json"})


def test_catalog_resolves_common_word_titles_through_one_phrase_query():
    # "Attention Is All You Need" has over a thousand keyword hits; paging
    # through them used to end in "Too many results" although the exact title
    # was the first result.
    transport = TitleSearchTransport(
        phrase_results=[
            EXACT_TITLE_ROW,
            {"id": "9", "arxiv_id": "2010.13154", "title": "Attention is All You Need in Speech Separation"},
        ],
        plain_has_exact=True,
    )
    catalog = CatalogClient(transport=transport)

    assert catalog.resolve_paper("Attention Is All You Need") == "1706.03762"
    assert [params["q"] for _path, params in transport.calls] == ['"Attention Is All You Need"']


def test_catalog_keeps_exact_matches_found_before_the_page_budget_runs_out():
    transport = TitleSearchTransport(phrase_results=[], plain_has_exact=True)
    catalog = CatalogClient(transport=transport)

    assert catalog.resolve_paper("Attention Is All You Need") == "1706.03762"
    assert len(transport.calls) == 11

    inconclusive = CatalogClient(
        transport=TitleSearchTransport(phrase_results=[], plain_has_exact=False)
    )
    with pytest.raises(ResponseError, match="Too many results"):
        inconclusive.resolve_paper("Attention Is All You Need")


def test_catalog_resolves_a_unique_short_name_before_the_title_colon():
    # Production chat: get_paper_info("MuseTalk") failed although the catalog
    # holds "MuseTalk: Real-Time High-Fidelity Video Dubbing ..." (2410.10122).
    musetalk = {
        "id": "90",
        "arxiv_id": "2410.10122",
        "title": "MuseTalk: Real-Time High-Fidelity Video Dubbing via Spatio-Temporal Sampling",
    }
    citing = {"id": "91", "arxiv_id": "2501.00001", "title": "Beyond MuseTalk: Faster Dubbing"}
    transport = TitleSearchTransport(phrase_results=[musetalk, citing], plain_has_exact=False)
    catalog = CatalogClient(transport=transport)

    assert catalog.resolve_paper("MuseTalk") == "2410.10122"
    assert catalog.resolve_paper("musetalk") == "2410.10122"

    twins = [musetalk, {**musetalk, "id": "92", "arxiv_id": "2502.00002"}]
    ambiguous = CatalogClient(
        transport=TitleSearchTransport(phrase_results=twins, plain_has_exact=False)
    )
    with pytest.raises(ResponseError, match="Paper title is ambiguous: MuseTalk"):
        ambiguous.resolve_paper("MuseTalk")


def test_catalog_resolves_a_unique_near_match_of_a_full_title():
    # Production chat: get_paper_info("BEIR: A Heterogeneous Benchmark ...")
    # failed although the catalog holds the arXiv spelling "Heterogenous"
    # (2104.08663), which keyword search returns first.
    beir = {
        "id": "5505",
        "arxiv_id": "2104.08663",
        "title": "BEIR: A Heterogenous Benchmark for Zero-shot Evaluation of Information Retrieval Models",
    }
    beir_nl = {
        "id": "93",
        "arxiv_id": "2412.08329",
        "title": "BEIR-NL: Zero-shot Information Retrieval Benchmark for the Dutch Language",
    }
    catalog = CatalogClient(
        transport=TitleSearchTransport(phrase_results=[beir, beir_nl], plain_has_exact=False)
    )

    assert catalog.resolve_paper(
        "BEIR: A Heterogeneous Benchmark for Zero-shot Evaluation of Information Retrieval Models"
    ) == "2104.08663"

    twins = [beir, {**beir, "id": "94", "arxiv_id": "2502.00003"}]
    ambiguous = CatalogClient(
        transport=TitleSearchTransport(phrase_results=twins, plain_has_exact=False)
    )
    with pytest.raises(ResponseError, match="Paper title is ambiguous"):
        ambiguous.resolve_paper(
            "BEIR: A Heterogeneous Benchmark for Zero-shot Evaluation of Information Retrieval Models"
        )


def test_near_title_rejects_short_names_and_other_editions():
    assert near_title(
        normalize_title("BEIR: A Heterogenous Benchmark for Zero-shot Evaluation"),
        normalize_title("BEIR: A Heterogeneous Benchmark for Zero-shot Evaluation"),
    )
    assert not near_title(normalize_title("MuseTalks"), normalize_title("MuseTalk"))
    assert not near_title(
        normalize_title("The Llama 3 Herd of Language Foundation Models"),
        normalize_title("The Llama 4 Herd of Language Foundation Models"),
    )
    assert not near_title(
        normalize_title("Deep Residual Learning for Image Recognition"),
        normalize_title("Deep Residual Learning for Video Recognition"),
    )


def test_catalog_reads_public_metadata_and_caches_lookups_including_misses():
    from pwc_cli.transport import HTTPStatusError

    class PublicTransport:
        def __init__(self):
            self.calls = []

        def get(self, path, params=None):
            self.calls.append((path, params))
            if path == "papers/2610.18869/public-metadata":
                return Response(
                    json.dumps({"in_catalog": False, "title": "Found"}).encode(), {}
                )
            if path == "papers/public-metadata/search":
                title = params["title"]
                if title == "Down Title":
                    raise HTTPStatusError(503, "unavailable")
                if title == "BERT":
                    raise HTTPStatusError(400, "title too short")
                if title == "Some Title":
                    return Response(
                        json.dumps({"in_catalog": False, "title": "Some title"}).encode(),
                        {},
                    )
                raise HTTPStatusError(404, "no exact title")
            if path.startswith("papers/Down/"):
                raise HTTPStatusError(503, "unavailable")
            if "%20" in path or path == "papers/BERT/public-metadata":
                raise HTTPStatusError(400, "titles are not identifiers")
            raise HTTPStatusError(404, "Paper not found")

    transport = PublicTransport()
    catalog = CatalogClient(transport=transport)

    assert catalog.public_paper(" 2610.18869 ")["title"] == "Found"
    assert catalog.public_paper("2610.18869")["title"] == "Found"
    assert catalog.public_paper("10.1/x") == PublicPaperMiss("identifier")
    assert catalog.public_paper("10.1/x") == PublicPaperMiss("identifier")
    # Titles the identifier route rejects are searched as exact titles.
    assert catalog.public_paper("Some Title") == {
        "in_catalog": False,
        "title": "Some title",
        "requested_title": "Some Title",
    }
    assert catalog.public_paper("Some Title")["title"] == "Some title"
    assert catalog.public_paper("Unknown Title") == PublicPaperMiss("title")
    assert catalog.public_paper("Unknown Title") == PublicPaperMiss("title")
    assert catalog.public_paper("BERT") == PublicPaperMiss("unsupported")
    # Upstream failures are best effort and not cached as misses.
    assert catalog.public_paper("Down") == PublicPaperMiss("unavailable")
    assert catalog.public_paper("Down") == PublicPaperMiss("unavailable")
    assert catalog.public_paper("Down Title") == PublicPaperMiss("unavailable")
    assert catalog.public_paper("Down Title") == PublicPaperMiss("unavailable")
    search = "papers/public-metadata/search"
    assert transport.calls == [
        ("papers/2610.18869/public-metadata", None),
        ("papers/10.1/x/public-metadata", None),
        ("papers/Some%20Title/public-metadata", None),
        (search, {"title": "Some Title"}),
        ("papers/Unknown%20Title/public-metadata", None),
        (search, {"title": "Unknown Title"}),
        ("papers/BERT/public-metadata", None),
        (search, {"title": "BERT"}),
        ("papers/Down/public-metadata", None),
        ("papers/Down/public-metadata", None),
        ("papers/Down%20Title/public-metadata", None),
        (search, {"title": "Down Title"}),
        ("papers/Down%20Title/public-metadata", None),
        (search, {"title": "Down Title"}),
    ]

#!/usr/bin/env python3
"""Install one checksum-verified prebuilt pwc CLI artifact."""

from __future__ import annotations

import argparse
import hashlib
import http.client
import json
import os
import platform
import re
import shlex
import shutil
import stat
import sys
import tempfile
import urllib.error
import urllib.request
from pathlib import Path

DEFAULT_RELEASE_ORIGIN = "https://github.com/huggingface/pwc-cli/releases/download"
DEFAULT_LATEST_RELEASE_URL = (
    "https://api.github.com/repos/huggingface/pwc-cli/releases/latest"
)
VERSION_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")


class NetworkError(Exception):
    """A concise installer networking failure."""


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--version",
        help="install an explicit release version instead of the latest release",
    )
    parser.add_argument("--prefix", type=Path, default=Path.home() / ".local")
    parser.add_argument(
        "--release-origin",
        default=DEFAULT_RELEASE_ORIGIN,
    )
    parser.add_argument(
        "--latest-release-url",
        default=DEFAULT_LATEST_RELEASE_URL,
        help=argparse.SUPPRESS,
    )
    return parser.parse_args(argv)


def _open(url: str):
    request = urllib.request.Request(
        url,
        headers={
            "Accept": "application/vnd.github+json",
            "User-Agent": "pwc-cli-installer",
        },
    )
    try:
        return urllib.request.urlopen(request, timeout=30)
    except (urllib.error.URLError, TimeoutError) as error:
        reason = str(getattr(error, "reason", error)).replace("\n", " ")
        raise NetworkError(reason) from error


def _validate_version(version: str) -> str:
    if not VERSION_RE.fullmatch(version):
        raise SystemExit(f"invalid release version: {version}")
    return version


def _read_response(response, maximum_bytes: int) -> bytes:
    try:
        contents = response.read(maximum_bytes + 1)
    except (OSError, http.client.HTTPException) as error:
        raise NetworkError(str(error)) from error
    if len(contents) > maximum_bytes:
        raise NetworkError("response was unexpectedly large")
    return contents


def resolve_version(explicit_version: str | None, latest_release_url: str) -> str:
    if explicit_version:
        return _validate_version(explicit_version)
    try:
        with _open(latest_release_url) as response:
            payload = json.loads(_read_response(response, 1024 * 1024))
        tag = payload["tag_name"]
    except NetworkError:
        raise
    except (KeyError, TypeError, ValueError) as error:
        raise NetworkError("latest release response was invalid") from error
    prefix = "pwc-cli-"
    if not isinstance(tag, str) or not tag.startswith(prefix):
        raise NetworkError("latest release tag was invalid")
    try:
        return _validate_version(tag.removeprefix(prefix))
    except SystemExit as error:
        raise NetworkError("latest release tag was invalid") from error


def _download(url: str, destination: Path) -> None:
    with _open(url) as response, destination.open("wb") as output:
        while True:
            try:
                chunk = response.read(1024 * 1024)
            except (OSError, http.client.HTTPException) as error:
                raise NetworkError(str(error)) from error
            if not chunk:
                break
            output.write(chunk)


def _read_checksum(url: str) -> str:
    with _open(url) as response:
        contents = _read_response(response, 4096)
    try:
        checksum = contents.decode("ascii", errors="strict").split()[0]
    except (IndexError, UnicodeDecodeError) as error:
        raise SystemExit("artifact checksum file was invalid") from error
    if len(checksum) != 64 or any(
        character not in "0123456789abcdefABCDEF" for character in checksum
    ):
        raise SystemExit("artifact checksum file was invalid")
    return checksum.lower()


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as artifact:
        for chunk in iter(lambda: artifact.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _install_atomically(artifact: Path, destination: Path) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    file_descriptor, temporary_name = tempfile.mkstemp(
        prefix=".pwc-install-", dir=destination.parent
    )
    os.close(file_descriptor)
    temporary = Path(temporary_name)
    try:
        shutil.copy2(artifact, temporary)
        temporary.chmod(
            temporary.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH
        )
        os.replace(temporary, destination)
    finally:
        temporary.unlink(missing_ok=True)


def report_path(bin_directory: Path, path_value: str | None = None) -> None:
    path_value = os.environ.get("PATH", "") if path_value is None else path_value
    expanded_bin = bin_directory.expanduser().resolve()
    entries = {
        Path(entry).expanduser().resolve()
        for entry in path_value.split(os.pathsep)
        if entry
    }
    display = (
        "~/.local/bin"
        if expanded_bin == (Path.home() / ".local/bin").resolve()
        else str(bin_directory)
    )
    shell_path = (
        '"$HOME/.local/bin:$PATH"'
        if display == "~/.local/bin"
        else f'{shlex.quote(str(expanded_bin))}:"$PATH"'
    )
    if expanded_bin in entries:
        print(f"{display} is on PATH", flush=True)
        return
    print(f"warning: {display} is not on PATH", file=sys.stderr, flush=True)
    print(
        f"Add this to ~/.profile: export PATH={shell_path}",
        file=sys.stderr,
        flush=True,
    )


def _print_network_error(error: NetworkError) -> None:
    message = str(error).replace("\r", " ").replace("\n", " ")
    print(f"pwc installer: network error: {message}", file=sys.stderr)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    try:
        version = resolve_version(args.version, args.latest_release_url)
    except NetworkError as error:
        _print_network_error(error)
        return 3

    machine = platform.machine().lower()
    system = platform.system().lower()
    machine = {"amd64": "x86_64", "aarch64": "arm64"}.get(machine, machine)
    supported = {
        ("linux", "x86_64"),
        ("darwin", "x86_64"),
        ("darwin", "arm64"),
    }
    if (system, machine) not in supported:
        raise SystemExit(f"unsupported platform: {system}-{machine}")
    artifact = f"pwc-{version}-{system}-{machine}"
    base = f"{args.release_origin.rstrip('/')}/pwc-cli-{version}"
    try:
        with tempfile.TemporaryDirectory(prefix="pwc-install-") as directory:
            target = Path(directory) / artifact
            _download(f"{base}/{artifact}", target)
            checksum = _read_checksum(f"{base}/{artifact}.sha256")
            if _sha256(target) != checksum:
                raise SystemExit("artifact checksum verification failed")
            destination = args.prefix / "bin" / "pwc"
            _install_atomically(target, destination)
    except NetworkError as error:
        _print_network_error(error)
        return 3
    report_path(destination.parent)
    os.execv(destination, [str(destination), "version"])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Private per-origin, per-paper credential files. Secrets never enter edit documents."""

import hashlib
import json
import os
from pathlib import Path
import stat
import tempfile

from pwc_cli.transport import ResponseError


class CredentialStore:
    def __init__(self, base_url: str):
        self.base_url = base_url
        self.root = Path.home() / ".config" / "pwc" / "edit-credentials"

    def path(self, paper_id: int) -> Path:
        key = hashlib.sha256(f"{self.base_url}:{paper_id}".encode()).hexdigest()
        return self.root / f"{key}.json"

    def save(self, paper_id: int, credential: dict) -> None:
        self.root.mkdir(parents=True, exist_ok=True, mode=0o700)
        info = self.root.lstat()
        if (
            not stat.S_ISDIR(info.st_mode)
            or info.st_uid != os.getuid()
            or info.st_mode & 0o077
        ):
            raise ResponseError(
                "Credential directory must be owned by you with mode 0700"
            )
        fd, name = tempfile.mkstemp(dir=self.root)
        try:
            with os.fdopen(fd, "w") as handle:
                json.dump({**credential, "base_url": self.base_url}, handle)
            os.replace(name, self.path(paper_id))
        finally:
            if os.path.exists(name):
                os.unlink(name)

    def load(self, paper_id: int) -> dict:
        path = self.path(paper_id)
        try:
            fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
        except FileNotFoundError as error:
            raise ResponseError(
                "No authorization for this paper and API. Run pwc auth login --paper PAPER"
            ) from error
        with os.fdopen(fd) as handle:
            info = os.fstat(handle.fileno())
            if (
                not stat.S_ISREG(info.st_mode)
                or info.st_uid != os.getuid()
                or info.st_mode & 0o077
            ):
                raise ResponseError(
                    "Credential file must be owned by you with mode 0600"
                )
            value = json.load(handle)
        if value.get("base_url") != self.base_url or value.get("paper_id") != paper_id:
            raise ResponseError("Credential origin or paper does not match")
        return value

    def remove(self, paper_id: int) -> None:
        self.path(paper_id).unlink(missing_ok=True)

